<?php declare(strict_types=1);
require __DIR__.'/lib.php';require_once __DIR__.'/lib/user_preferences.php';lab_auth_require_admin();require_once __DIR__.'/lib/playback_diagnostics.php';
$sfTheme=lab_user_theme((string)(lab_auth_current_account()['id']??''));
$embed=!empty($_GET['embed']);$settings=sf_playback_debug_settings(lab_load_config());$events=sf_playback_read_events(LAB_DATA.'/playback-diagnostics',400);
if(isset($_GET['export'])){header('Content-Type: application/x-ndjson');header('Content-Disposition: attachment; filename="sparrowfy-playback.jsonl"');header('Cache-Control: no-store');foreach($events as $row)echo json_encode($row,JSON_UNESCAPED_UNICODE)."\n";exit;}
$starts=[];$buffer=0;$errors=0;$warnings=0;$retries=0;foreach($events as $e){if(isset($e['startup_ms']))$starts[]=(float)$e['startup_ms'];if($e['event']==='buffer_end')$buffer+=(float)($e['buffer_ms']??0);if($e['event']==='media_error'||($e['event']==='hls_error'&&!empty($e['fatal'])))$errors++;elseif($e['event']==='hls_error')$warnings++;if($e['event']==='retry')$retries++;}sort($starts);
function sf_diag_percentile(array $values,float $q): string {return $values?number_format($values[(int)floor((count($values)-1)*$q)]/1000,2).' s':'—';}
?><!doctype html><html lang="es" data-theme="<?=lab_h($sfTheme)?>" data-theme-source="server"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Diagnóstico de reproducción · Sparrow-Fy</title><link rel="stylesheet" href="assets/lab.css?v=theme-sweep1"><style>.diag-main{max-width:1200px;margin:auto;padding:20px}.diag-head{display:flex;justify-content:space-between;align-items:center;gap:16px}.diag-summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px}.diag-stat{padding:14px;background:var(--panel,#10272d);border:1px solid var(--border,#315563);border-radius:10px}.diag-stat strong{display:block;font-size:1.4rem;margin-top:8px}.diag-table{width:100%;border-collapse:collapse;font-size:.85rem}.diag-table td,.diag-table th{padding:9px;text-align:left;border-bottom:1px solid var(--border,#315563)}.diag-table-wrap{overflow:auto}.diag-actions{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}</style><meta name="sf-session-account" content="<?= htmlspecialchars((string)(lab_auth_current_account()['id']??''), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') ?>"><script src="assets/session-sync.js?v=auth-poll3" defer></script>
<script defer src=assets/sf-language.js></script></head><body><main class="diag-main"><header class="diag-head"><h1>Diagnóstico de reproducción</h1><a class="btn" href="config.php<?=$embed?'?embed=1':''?>">Volver atrás</a></header><p class="muted">Estado: <?=$settings['enabled']?'activado':'desactivado'?> · Registro en servidor: <?=$settings['enabled']&&$settings['record']?'activado':'desactivado'?>. Muestra los últimos <?=count($events)?> eventos disponibles; no representa todo el tráfico del sitio.</p><section class="diag-summary"><div class="diag-stat">Inicio mediano<strong><?=sf_diag_percentile($starts,.5)?></strong></div><div class="diag-stat">Inicio p95<strong><?=sf_diag_percentile($starts,.95)?></strong></div><div class="diag-stat">Tiempo sin búfer<strong><?=number_format($buffer/1000,1)?> s</strong></div><div class="diag-stat">Errores críticos<strong><?=$errors?></strong></div><div class="diag-stat">Avisos HLS recuperables<strong><?=$warnings?></strong></div><div class="diag-stat">Reintentos<strong><?=$retries?></strong></div></section><div class="diag-actions"><a class="btn" href="playback_diagnostics.php<?=$embed?'?embed=1':''?>">Actualizar</a><a class="btn" href="playback_diagnostics.php?export=1">Descargar registros</a></div><p class="muted">Identificadores internos de cuenta y pista; no contiene claves, cookies ni URLs de reproducción. Retención configurada: <?=$settings['retention']?> días; máximo 5 MiB diarios.</p><div class="diag-table-wrap"><table class="diag-table"><thead><tr><th>Fecha</th><th>Cuenta / pista</th><th>Evento</th><th>Detalle</th></tr></thead><tbody><?php foreach($events as $e): $extra=$e;foreach(['time','user','track','event'] as $k)unset($extra[$k]);?><tr><td><?=lab_h((new DateTimeImmutable($e['time']??'now'))->setTimezone(new DateTimeZone('America/Mexico_City'))->format('d/m/Y H:i:s'))?></td><td><?=lab_h($e['user']??'')?> / <?=lab_h($e['track']??'—')?></td><td><?=lab_h($e['event']??'')?></td><td><?=lab_h(json_encode($extra,JSON_UNESCAPED_UNICODE))?></td></tr><?php endforeach;if(!$events):?><tr><td colspan="4">Todavía no hay registros. Activa el diagnóstico y su registro desde Configuración para investigar una reproducción.</td></tr><?php endif;?></tbody></table></div></main></body></html>
